local function D(s)
    s=s:gsub("[^"..B.."=]","")
    local out={}
    local n=0
    local buf=0
    for i=1,#s do
        local c=s:sub(i,i)
        if c~="=" then
            local p=B:find(c,1,true)
            if p then
                buf=buf*64+(p-1)
                n=n+6
                if n>=8 then
                    n=n-8
                    local v=math.floor(buf/2^n)%256
                    out[#out+1]=string.char((v-K)%256)
                    buf=buf%2^n
                end
            end
        end
    end
    return table.concat(out)
end

